#include <Arduino.h>
#include <TM1637Display.h>

TM1637Display display(4, 5);
bool automaticMode = true;
bool running = false;
bool manualUsed = false;
unsigned long runStarted = 0;
int lastRaw = HIGH;
int stableButton = HIGH;
unsigned long changedAt = 0;
unsigned long displayedAt = 0;
bool firstDisplay = true;

void handlePress(unsigned long now) {
  if (automaticMode) {
    automaticMode = false;
    running = false;
    manualUsed = false;
  } else if (!manualUsed) {
    running = true;
    manualUsed = true;
    runStarted = now;
  } else {
    automaticMode = true;
    running = false;
  }
}

void setup() {
  pinMode(2, INPUT_PULLUP);
  pinMode(10, OUTPUT);
  pinMode(13, OUTPUT);
  pinMode(6, OUTPUT);
  digitalWrite(10, LOW);
  digitalWrite(13, LOW);
  display.setBrightness(5);
}

void loop() {
  unsigned long now = millis();
  int raw = digitalRead(2);
  if (raw != lastRaw) {
    lastRaw = raw;
    changedAt = now;
  }
  if (raw != stableButton && now - changedAt >= 30) {
    stableButton = raw;
    if (stableButton == LOW) handlePress(now);
  }

  int soil = analogRead(A0);
  int rain = analogRead(A1);
  int water = analogRead(A2);
  bool enoughWater = water >= 500;
  bool pump;
  if (automaticMode) {
    pump = soil > 500 && rain > 500 && enoughWater;
  } else {
    if (running && now - runStarted >= 5000UL) running = false;
    pump = running;
  }
  digitalWrite(10, pump ? HIGH : LOW);
  digitalWrite(13, pump ? HIGH : LOW);
  if (automaticMode && !enoughWater) tone(6, 2000);
  else noTone(6);

  if (firstDisplay || now - displayedAt >= 100) {
    firstDisplay = false;
    displayedAt = now;
    unsigned int page = (now / 1500UL) % 3;
    int value = page == 0 ? soil : (page == 1 ? water : (automaticMode ? 0 : 1));
    display.showNumberDec(value, false);
  }
}
